// prog1: Fraction Sum
// Input: n fractions a_i/b_i, output their sum in simplest form
#include <iostream>
using namespace std;

typedef long long ll;

ll gcd(ll a, ll b) {
    while (b) { ll t = a % b; a = b; b = t; }
    return a;
}

int main(){
    int n;
    cin >> n;
    ll num = 0, den = 1; // running sum = num/den
    for(int i = 0; i < n; i++){
        ll a, b;
        cin >> a >> b;
        // num/den + a/b = (num*(b/g) + a*(den/g)) / lcm(den,b)
        // where g = gcd(den, b), lcm = den/g*b
        ll g = gcd(den, b);
        ll new_den = den / g * b;
        ll new_num = num * (b / g) + a * (den / g);
        ll g2 = gcd((new_num < 0 ? -new_num : new_num), new_den);
        num = new_num / g2;
        den = new_den / g2;
    }
    if(den == 1)
        cout << num << endl;
    else
        cout << num << "/" << den << endl;
    return 0;
}

