// 测试程序：验证「分数求和」考生程序的正确性
// 用法： g++ -O2 -std=c++14 -o tester tester.cpp
//        ./tester <考生二进制程序路径>
// 原理：把每组用例输入写入临时文件，重定向给考生程序运行，捕获其标准输出并与期望结果比较（忽略首尾空白）。
// 全部通过时退出码为 0；存在失败用例时退出码为 1，并用表格打印 输入/期望/实际。
#include <cstdio>
#include <cstdlib>
#include <string>
#include <vector>
#include <sstream>
#include <fstream>
#include <iostream>
#include <unistd.h>

struct Case { std::string input; std::string expected; };

static std::string trim(const std::string& s) {
    size_t a = s.find_first_not_of(" \t\r\n");
    if (a == std::string::npos) return "";
    size_t b = s.find_last_not_of(" \t\r\n");
    return s.substr(a, b - a + 1);
}

static std::string flat(std::string s) { for (auto& c : s) if (c == '\n') c = ' '; return s; }

static std::string runProgram(const std::string& exePath, const std::string& input) {
    std::string inFile = "/tmp/e12p1_in_" + std::to_string(getpid()) + ".txt";
    std::string outFile = "/tmp/e12p1_out_" + std::to_string(getpid()) + ".txt";
    { std::ofstream fin(inFile); fin << input; }
    std::string cmd = "\"" + exePath + "\" < \"" + inFile + "\" > \"" + outFile + "\" 2>/dev/null";
    int rc = system(cmd.c_str()); (void)rc;
    std::ifstream fout(outFile);
    std::stringstream ss; ss << fout.rdbuf();
    std::remove(inFile.c_str()); std::remove(outFile.c_str());
    return trim(ss.str());
}

int main(int argc, char** argv) {
    if (argc < 2) { std::cerr << "用法: " << argv[0] << " <考生二进制程序路径>\n"; return 1; }
    std::string exePath = argv[1];

    std::vector<Case> cases = {
        { "2\n1 2\n1 3\n", "5/6" },  // 基础异分母
        { "1\n4 8\n", "1/2" },  // n=1需约分
        { "2\n1 2\n1 2\n", "1" },  // 结果为整数
        { "3\n1 6\n1 3\n1 2\n", "1" },  // 三分数恰为1
        { "2\n1 999999937\n1 999999938\n", "1999999875/999999875000003906" },  // 大分母lcm近1e18
        { "4\n1 4\n1 4\n1 4\n1 4\n", "1" },  // 四个1/4
        { "2\n3 4\n5 6\n", "19/12" },  // 19/12
        { "2\n1000000000 999999937\n1 999999937\n", "1000000001/999999937" },  // 同分母大分子
        { "3\n2 3\n4 6\n1 9\n", "13/9" },  // 含可约分输入
        { "10\n1 2\n1 2\n1 2\n1 2\n1 2\n1 2\n1 2\n1 2\n1 2\n1 2\n", "5" },  // 十个1/2
        { "1\n1000000000 1000000000\n", "1" },  // 1e9/1e9=1
    };

    int total = (int)cases.size();
    int passed = 0;
    std::vector<int> failedIdx;
    std::vector<std::string> actualOutputs(total);

    for (int i = 0; i < total; i++) {
        std::string actual = runProgram(exePath, cases[i].input);
        actualOutputs[i] = actual;
        if (actual == trim(cases[i].expected)) passed++;
        else failedIdx.push_back(i);
    }

    printf("=== 分数求和 测试结果：%d / %d 通过 ===\n", passed, total);

    if (!failedIdx.empty()) {
        printf("\n以下用例不符合预期：\n");
        printf("%-4s | %-32s | %-32s | %-32s\n", "#", "输入", "期望输出", "实际输出");
        printf("------------------------------------------------------------------------------------------------------\n");
        for (int idx : failedIdx) {
            printf("%-4d | %-32.32s | %-32.32s | %-32.32s\n", idx + 1,
                flat(cases[idx].input).c_str(), flat(cases[idx].expected).c_str(), flat(actualOutputs[idx]).c_str());
        }
        return 1;
    }
    printf("全部通过\n");
    return 0;
}

