// prog2: Bitmask Set Operations
// Input: two sets A and B (subsets of {0..30})
// Output: |A|, |B|, |A∪B|, elements of A∪B sorted ascending (or EMPTY)
#include <iostream>
#include <cstdint>
using namespace std;

int popcount32(unsigned int x) {
    int cnt = 0;
    while (x) { x &= (x - 1); cnt++; }
    return cnt;
}

int main(){
    unsigned int A = 0, B = 0;
    int k;
    cin >> k;
    for(int i = 0; i < k; i++){
        int v; cin >> v;
        A |= (1u << v);
    }
    cin >> k;
    for(int i = 0; i < k; i++){
        int v; cin >> v;
        B |= (1u << v);
    }
    unsigned int U = A | B;
    cout << popcount32(A) << endl;
    cout << popcount32(B) << endl;
    cout << popcount32(U) << endl;
    if (U == 0) {
        cout << "EMPTY" << endl;
    } else {
        bool first = true;
        for(int i = 0; i <= 30; i++){
            if (U & (1u << i)){
                if (!first) cout << " ";
                cout << i;
                first = false;
            }
        }
        cout << endl;
    }
    return 0;
}

